INSERT INTO `block_content_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('basic', 0, 1, 1, 'en', 0, '<div class=\"text-right\"><img alt=\"img\" src=\"https://gaviasthemes.net/drupal/batiz/sites/default/files/other/adv-header.jpg\" /></div>\r\n', '', 'restricted_html'),
('basic', 0, 2, 2, 'en', 0, '<div class=\"pull-left text-left\">\r\n      <ul class=\"inline\">\r\n            <li><span> <i class=\"fa fa-clock-o\"></i>Mon - Fri : 09:00 - 17:00</span> </li>\r\n           <li><span><i class=\"fa fa-envelope\"></i>contact@foxin-demo.com</span></li>\r\n      </ul>\r\n</div>\r\n<div class=\"pull-right text-right\">\r\n     <ul class=\"inline\">\r\n           <li><a target=\"_blank\" href=\"#\"><i class=\"fa fa-facebook\"></i></a></li>\r\n           <li><a target=\"_blank\" href=\"#\"> <i class=\"fa fa-flickr\"></i></a></li>\r\n          <li><a target=\"_blank\" href=\"#\"><i class=\"fa fa-linkedin\"></i></a></li>\r\n          <li><a target=\"_blank\" href=\"#\"><i class=\"fa fa-pinterest-p\"></i></a></li>\r\n          <li><a target=\"_blank\" href=\"#\"><i class=\"fa fa-twitter\"></i></a></li>\r\n      </ul>\r\n</div>', '', 'restricted_html'),
('basic', 0, 5, 5, 'en', 0, '<div class=\"row\">\r\n    <div class=\"col-sm-12\">\r\n       <ul class=\"menu\">\r\n	  <li><a href=\"#\">About Us</a></li>\r\n	  <li><a href=\"#\">Advertise</a></li>\r\n	  <li><a href=\"#\"> Terms & Conditions</a></li>\r\n	  <li><a href=\"#\"> Privacy Policy</a></li>\r\n	  <li><a href=\"#\"> Careers</a></li>\r\n          <li><a href=\"#\"> News</a></li>\r\n       </ul>      \r\n    </div>\r\n</div>   ', '', 'restricted_html'),
('basic', 0, 6, 6, 'en', 0, '<div class=\"clearfix box-logo-footer\">\r\n   <p><img src=\"http://localhost/private/batiz/sites/default/files/other/logo.png\" alt=\"\"/></p>\r\n   <p>Class aptent taciti sociosqu ad litora torquent per conubia nostra, per inceptos himenaeos. Cras eleifend egestas justo.</p>\r\n</div>', '', 'restricted_html'),
('basic', 0, 7, 7, 'en', 0, '<div class=\"text-center\">\r\n© Copyright <a href=\"http://themeforest.net/user/gavias\">GaviasThemes</a> 2018. All Rights Reserved. \r\n</div>\r\n', '', 'restricted_html'),
('basic', 0, 8, 8, 'en', 0, '<div class=\"contact-info\">\r\n    <span class=\"description\"> Class aptent taciti sociosqu ad litora torquent per conubia nostra, per inceptos himenaeos. Cras eleifend egestas justo.</span>\r\n	<ul class=\"contact-info\">\r\n		<li><span><i class=\"fa fa-home\"></i> 2 Queen Street,California, USA </span> </li>\r\n		<li><span><i class=\"fa fa-mobile-phone\"></i> (+84) 04 123 456</span></li>\r\n		<li><a href=\"mailto:info@yourstore.com\"><i class=\"fa fa-envelope-o\"></i> info@yourstore.com</a> </li>\r\n		<li><span><i class=\"fa fa-skype\"></i> skype</span> </li>\r\n	</ul>\r\n</div>', '', 'restricted_html'),
('basic', 0, 9, 9, 'en', 0, '<div class=\"social-border\"> \r\n    <div class=\"socials\"> \r\n        <a href=\"#\"><i class=\"fa fa-facebook\"></i></a>\r\n        <a href=\"#\"><i class=\"fa fa-twitter\"></i></a>\r\n        <a href=\"#\"><i class=\"fa fa-behance\"></i></a>\r\n        <a href=\"#\"><i class=\"fa fa-google-plus\"></i></a> \r\n        <a href=\"#\"><i class=\"fa fa-skype\"></i></a> \r\n     </div>\r\n</div>', '', 'restricted_html'),
('basic', 0, 10, 10, 'en', 0, '<div class=\"penci-socials\">\r\n	<div class=\"social-item social-facebook\">\r\n		<div class=\"social-content\">\r\n			<a href=\"#\" target=\"_blank\"><i class=\"fa fa-facebook\"></i><span class=\"social-name\">Facebook</span><span class=\"social-btn\"><i class=\"fa fa-thumbs-o-up\"></i>Like</span></a>\r\n		</div>\r\n	</div>\r\n	<div class=\"social-item social-twitter\">\r\n		<div class=\"social-content\">\r\n			<a href=\"#\" target=\"_blank\"><i class=\"fa fa-twitter\"></i><span class=\"social-name\">Twitter</span><span class=\"social-btn\"><i class=\"fa fa-user-plus\"></i>Follow</span></a>\r\n		</div>\r\n	</div>\r\n	<div class=\"social-item social-instagram\">\r\n		<div class=\"social-content\">\r\n			<a href=\"http://instagram.com/#\" target=\"_blank\"><i class=\"fa fa-instagram\"></i><span class=\"social-name\">Instagram</span><span class=\"social-btn\"><i class=\"fa fa-user-plus\"></i>Follow</span></a>\r\n		</div>\r\n	</div>\r\n	<div class=\"social-item social-youtube\">\r\n		<div class=\"social-content\">\r\n			<a href=\"#\" target=\"_blank\"><i class=\"fa fa-youtube-play\"></i><span class=\"social-name\">Youtube</span><span class=\"social-btn\"><i class=\"fa fa-user-plus\"></i>Subscribe</span></a>\r\n		</div>\r\n	</div>\r\n	<div class=\"social-item social-vimeo\">\r\n		<div class=\"social-content\">\r\n		<a href=\"#\" target=\"_blank\"><i class=\"fa fa-vimeo\"></i><span class=\"social-name\">Vimeo</span><span class=\"social-btn\"><i class=\"fa fa-thumbs-o-up\"></i>Like</span></a>\r\n		</div>\r\n	</div>\r\n	<div class=\"social-item social-rss\">\r\n		<div class=\"social-content\">\r\n			<a href=\"#\" target=\"_blank\"><i class=\"fa fa-rss\"></i><span class=\"social-name\">Rss</span><span class=\"social-btn\"><i class=\"fa fa-user-plus\"></i>Follow</span></a>\r\n		</div>\r\n	</div>\r\n</div>', '', 'restricted_html');
